package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*;
class TournamentRegistrationSliceTest { @Test void openTournamentAcceptsOneRegistration() throws Exception {Path p=Files.createTempFile("tournament-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("organizer","password1");var u=us.authenticate("organizer","password1");var o=new OperationsService(db);long t=o.createTournament(u.id(),"Summer Cup","SINGLE_ELIMINATION",2500);long r=o.registerTournament(t,u.id());assertTrue(r>0);assertThrows(IllegalStateException.class,()->o.registerTournament(t,u.id()));}finally{Files.deleteIfExists(p);}}}
